<?php
declare(strict_types=1);
if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/_quiz_lib.php';
if(!isset($_SESSION['academic_logged'])||$_SESSION['academic_logged']!==true){header('Location: /lessons/lessons/academic/login.php');exit;}
function tq_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function tq_is_image($v):bool{$v=trim((string)$v);if($v==='')return false;if(str_starts_with($v,'data:image/'))return true;$p=(string)(parse_url($v,PHP_URL_PATH)??'');return(bool)preg_match('/\.(png|jpe?g|gif|webp|svg)$/i',$p);}
function tq_media($v,string $alt='',string $class='quiz-media'):string{$v=trim((string)$v);if($v==='')return'';return tq_is_image($v)?'<img class="'.tq_h($class).'" src="'.tq_h($v).'" alt="'.tq_h($alt).'" loading="eager">':tq_h($v);}
function tq_redirect(array $p):void{header('Location: teacher_viewer.php?'.http_build_query($p));exit;}
function tq_result_totals(array $quiz,array $answers):array{$s=qz_answers_totals($quiz,$answers);$qt=count($quiz);$cq=(int)($s['correct_questions']??0);$pp=max(0,(int)($s['possible']??0));$ep=max(0.0,min((float)$pp,(float)($s['earned']??0)));$pc=$pp>0?(int)round(($ep/$pp)*100):0;return['question_total'=>$qt,'correct_questions'=>$cq,'question_errors'=>max(0,$qt-$cq),'possible_points'=>$pp,'earned_points'=>$ep,'percent'=>max(0,min(100,$pc)),'skipped'=>max(0,(int)($s['skipped_questions']??0))];}
function tq_platform_summary(PDO $pdo,string $teacherId,string $assignmentId,string $unitId,int $quizPercent):array{
  $rows=[];
  try{$pdo->exec("CREATE TABLE IF NOT EXISTS teacher_activity_results (teacher_id TEXT NOT NULL,assignment_id TEXT NOT NULL,unit_id TEXT NOT NULL,activity_id TEXT NOT NULL,percent INTEGER NOT NULL DEFAULT 0,errors_count INTEGER NOT NULL DEFAULT 0,total_questions INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY (teacher_id,assignment_id,unit_id,activity_id))");$st=$pdo->prepare("SELECT r.activity_id,r.percent,r.errors_count,r.total_questions,a.type FROM teacher_activity_results r LEFT JOIN activities a ON a.id::text=r.activity_id WHERE r.teacher_id=:teacher AND r.assignment_id=:assignment AND r.unit_id=:unit AND r.activity_id<>'unit_quiz' ORDER BY r.percent ASC,r.updated_at DESC");$st->execute(['teacher'=>$teacherId,'assignment'=>$assignmentId,'unit'=>$unitId]);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}
  $scores=[];$feedback=[];$labels=['multiple_choice'=>'Multiple Choice','video_comprehension'=>'Video Comprehension','hangman'=>'Hangman','pronunciation'=>'Pronunciation','listen_order'=>'Listen & Order','order_sentences'=>'Order Sentences','drag_drop'=>'Unscramble','drag_drop_kids'=>'Drag & Drop','match'=>'Matching','fill'=>'Fill in','dictation'=>'Dictation','writing'=>'Writing Practice','reading_comprehension'=>'Reading Comprehension'];
  foreach($rows as$row){$pct=max(0,min(100,(int)($row['percent']??0)));$scores[]=$pct;if(count($feedback)<3&&$pct<80){$type=strtolower(trim((string)($row['type']??'activity')));$feedback[]=['label'=>$labels[$type]??ucwords(str_replace('_',' ',$type)),'percent'=>$pct,'errors'=>max(0,(int)($row['errors_count']??0)),'total'=>max(0,(int)($row['total_questions']??0)),'href'=>'/lessons/lessons/academic/teacher_course.php?'.http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'step'=>0])];}}
  $unitPercent=$scores?(int)round(array_sum($scores)/count($scores)):$quizPercent;
  $finalPercent=$scores?(int)round(($unitPercent+$quizPercent)/2):$quizPercent;
  return['unit_percent'=>$unitPercent,'quiz_percent'=>$quizPercent,'final_percent'=>max(0,min(100,$finalPercent)),'feedback'=>$feedback,'activity_count'=>count($scores)];
}
function tq_save_teacher_score(PDO $pdo,string $teacherId,string $assignmentId,string $unitId,array $r,int $finalPercent):void{$pdo->exec("CREATE TABLE IF NOT EXISTS teacher_unit_results (teacher_id TEXT NOT NULL,assignment_id TEXT NOT NULL,unit_id TEXT NOT NULL,completion_percent INTEGER NOT NULL DEFAULT 0,quiz_errors INTEGER NOT NULL DEFAULT 0,quiz_total INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY (teacher_id,assignment_id,unit_id))");$st=$pdo->prepare("INSERT INTO teacher_unit_results (teacher_id,assignment_id,unit_id,completion_percent,quiz_errors,quiz_total,updated_at) VALUES (:teacher_id,:assignment_id,:unit_id,:percent,:errors,:total,NOW()) ON CONFLICT (teacher_id,assignment_id,unit_id) DO UPDATE SET completion_percent=GREATEST(teacher_unit_results.completion_percent,EXCLUDED.completion_percent),quiz_errors=CASE WHEN EXCLUDED.completion_percent>=teacher_unit_results.completion_percent THEN EXCLUDED.quiz_errors ELSE teacher_unit_results.quiz_errors END,quiz_total=CASE WHEN EXCLUDED.completion_percent>=teacher_unit_results.completion_percent THEN EXCLUDED.quiz_total ELSE teacher_unit_results.quiz_total END,updated_at=NOW()");$st->execute(['teacher_id'=>$teacherId,'assignment_id'=>$assignmentId,'unit_id'=>$unitId,'percent'=>$finalPercent,'errors'=>(int)$r['question_errors'],'total'=>(int)$r['question_total']]);}
function tq_append_result_to_return(string $returnTo,array $r,int $finalPercent):string{$t=trim($returnTo)!==''?$returnTo:'/lessons/lessons/academic/teacher_course.php';$sep=str_contains($t,'?')?'&':'?';return$t.$sep.http_build_query(['activity_total'=>(int)$r['question_total'],'activity_errors'=>(int)$r['question_errors'],'activity_percent'=>$finalPercent,'activity_id'=>'unit_quiz','quiz_total'=>(int)$r['question_total'],'quiz_errors'=>(int)$r['question_errors'],'quiz_percent'=>(int)$r['percent']]);}
function tq_drag_instruction(array $q):string{$instruction=(string)($q['instruction']??'');$words=(array)($q['correct_words']??[]);if($instruction==='')$instruction=implode(' ',array_fill(0,max(1,count($words)),'___'));return $instruction;}
function tq_quiz_complete(array $quiz,array $answers):bool{if(empty($quiz))return false;foreach(array_keys($quiz)as$index){if(!array_key_exists($index,$answers)||!is_array($answers[$index]))return false;}return true;}
$assignmentId=trim((string)($_GET['assignment']??''));$unitId=trim((string)($_GET['unit']??''));$returnTo=trim((string)($_GET['return_to']??''));$mode=trim((string)($_GET['mode']??'intro'));$questionIndex=max(0,(int)($_GET['q']??0));$teacherId=trim((string)($_SESSION['teacher_id']??''));
if($assignmentId===''||$unitId===''||$teacherId===''){http_response_code(400);exit('Missing teacher, assignment, or unit information.');}
$st=$pdo->prepare('SELECT id FROM teacher_assignments WHERE id=:assignment AND teacher_id=:teacher LIMIT 1');$st->execute(['assignment'=>$assignmentId,'teacher'=>$teacherId]);if(!$st->fetchColumn()){http_response_code(403);exit('You do not have permission to open this quiz.');}
$st=$pdo->prepare('SELECT id,type,unit_id,data FROM activities WHERE unit_id::text=:unit ORDER BY id ASC');$st->execute(['unit'=>$unitId]);$activities=$st->fetchAll(PDO::FETCH_ASSOC)?:[];$allQuestions=[];foreach($activities as$activity){foreach(qz_normalize_activity($activity)as$question){if(($question['type']??'')!=='pronunciation')$allQuestions[]=$question;}}
if(!$allQuestions)exit('<div style="font-family:Arial;padding:30px;color:#7F77DD"><h2>No scoreable quiz questions were found for this unit.</h2></div>');
$baseKey='teacher_quiz_'.md5($teacherId.'|'.$assignmentId.'|'.$unitId);$attemptKey=$baseKey.'_attempt';$historyKey=$baseKey.'_history';if(!isset($_SESSION[$attemptKey]))$_SESSION[$attemptKey]=1;if(!isset($_SESSION[$historyKey])||!is_array($_SESSION[$historyKey]))$_SESSION[$historyKey]=[];$attempt=max(1,min(2,(int)$_SESSION[$attemptKey]));$quizKey=$baseKey.'_set_'.$attempt;$answersKey=$baseKey.'_answers_'.$attempt;if(!isset($_SESSION[$quizKey])||!is_array($_SESSION[$quizKey]))$_SESSION[$quizKey]=qz_build($allQuestions,$unitId,$assignmentId,$attempt);if(!isset($_SESSION[$answersKey])||!is_array($_SESSION[$answersKey]))$_SESSION[$answersKey]=[];$quiz=$_SESSION[$quizKey];$answers=&$_SESSION[$answersKey];$totalQuestions=count($quiz);
if(isset($_GET['restart'])&&$_GET['restart']==='1'){$last=$_SESSION[$historyKey][$attempt]??null;if($attempt<2&&is_array($last)&&(int)($last['percent']??100)<65){$_SESSION[$attemptKey]=2;unset($_SESSION[$baseKey.'_set_2'],$_SESSION[$baseKey.'_answers_2']);tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'intro']);}$mode='result';}
if($_SERVER['REQUEST_METHOD']==='POST'&&$mode==='quiz'){$questionIndex=max(0,min($questionIndex,$totalQuestions-1));if(!array_key_exists($questionIndex,$answers)){$q=$quiz[$questionIndex];if(isset($_POST['skip'])){$score=qz_answer_score($q,null);$answers[$questionIndex]=['answer'=>null,'skipped'=>true,'correct'=>false,'earned'=>0.0,'possible'=>$score['possible']];}else{$answer=in_array($q['type'],['match','drag_drop'],true)?(isset($_POST['answer'])&&is_array($_POST['answer'])?$_POST['answer']:[]):trim((string)($_POST['answer']??''));$score=qz_answer_score($q,$answer);$answers[$questionIndex]=['answer'=>$answer,'skipped'=>false,'correct'=>(bool)$score['correct'],'earned'=>(float)$score['earned'],'possible'=>(int)$score['possible']];}}$next=$questionIndex+1;while($next<$totalQuestions&&array_key_exists($next,$answers))$next++;if($questionIndex>=$totalQuestions-1||$next>=$totalQuestions){foreach($quiz as$missingIndex=>$missingQuestion){if(array_key_exists($missingIndex,$answers))continue;$missingScore=qz_answer_score($missingQuestion,null);$answers[$missingIndex]=['answer'=>null,'skipped'=>true,'correct'=>false,'earned'=>0.0,'possible'=>$missingScore['possible']];}tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'result']);}tq_redirect(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'quiz','q'=>$next]);}
$result=tq_result_totals($quiz,$answers);$summary=tq_platform_summary($pdo,$teacherId,$assignmentId,$unitId,(int)$result['percent']);$isComplete=tq_quiz_complete($quiz,$answers);if($mode==='result'&&$isComplete){$_SESSION[$historyKey][$attempt]=$result;tq_save_teacher_score($pdo,$teacherId,$assignmentId,$unitId,$result,(int)$summary['final_percent']);}$courseReturn=tq_append_result_to_return($returnTo,$result,(int)$summary['final_percent']);$currentQuestion=$quiz[max(0,min($questionIndex,$totalQuestions-1))]??null;$canRetry=$isComplete&&$attempt<2&&(int)$result['percent']<65;$quizTypeFeedback=qz_quiz_feedback_by_type($quiz,$answers);$quizStudyLabels=qz_quiz_feedback_labels($quizTypeFeedback);
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unit Quiz</title><style>
:root{--purple:#7F77DD;--purple-dark:#534AB7;--purple-soft:#EEEDFE;--orange:#F97316;--line:#EDE9FA;--ink:#14113A;--muted:#8178B6;--bg:#F8F7FF}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Nunito,Arial,sans-serif;color:var(--ink)}.page{max-width:820px;margin:auto;padding:28px 18px 50px}.top,.card{background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:0 8px 28px rgba(127,119,221,.10)}.top{padding:16px 20px;margin-bottom:18px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-weight:900;color:var(--purple)}.back,.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:0;border-radius:12px;padding:12px 18px;font-weight:900;cursor:pointer}.back{background:#F0EEF8;color:var(--purple)}.card{padding:28px}.kicker{display:inline-block;background:#FFF0E6;color:#C2580A;border-radius:999px;padding:6px 13px;font-size:12px;font-weight:900}.title{font-size:34px;color:var(--orange);margin:12px 0}.lead{color:var(--muted);font-weight:700;line-height:1.5}.chips{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.chip{background:#F0EEF8;color:var(--purple);border-radius:999px;padding:7px 11px;font-size:12px;font-weight:900}.btn{background:var(--purple);color:#fff}.btn.orange{background:var(--orange)}.btn.light{background:#fff;color:var(--purple);border:1px solid var(--line)}.w100{width:100%}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions>*{flex:1;min-width:150px}.progress{height:9px;background:#EEEAF9;border-radius:999px;overflow:hidden;margin:10px 0 22px}.progress>div{height:100%;background:linear-gradient(90deg,var(--orange),var(--purple))}.question{font-size:23px;font-weight:900;line-height:1.4;margin:12px 0}.question-media{display:flex;justify-content:center;margin:12px 0 18px}.quiz-media{display:block;max-width:100%;max-height:240px;object-fit:contain;border-radius:16px}.option{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid var(--line);border-radius:14px;margin:10px 0;font-weight:800;cursor:pointer}.option:has(input:checked){border-color:var(--purple);background:#F8F7FF}.option.image-option{align-items:flex-start}.option-image{display:block;max-width:100%;max-height:180px;object-fit:contain;margin:0 auto;border-radius:12px}.option-content{flex:1;min-width:0}.image-option .option-content{display:flex;justify-content:center}.input,.select{width:100%;padding:14px;border:1px solid var(--line);border-radius:12px;font:700 16px Nunito,Arial;margin:8px 0}.listen-box{display:flex;align-items:center;gap:12px;background:#F8F7FF;border:1px solid var(--line);border-radius:16px;padding:14px;margin:12px 0}.listen-btn{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:12px;padding:12px 18px;background:var(--purple);color:#fff;font-weight:900;cursor:pointer}.listen-btn.playing{background:var(--orange)}.listen-status{color:var(--muted);font-size:13px;font-weight:800}.match-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-items:center;margin:8px 0}.match-left{display:flex;align-items:center;gap:10px}.match-left img{max-width:120px;max-height:100px;object-fit:contain}.dd-shell{border:1px solid #F0EEF8;border-radius:28px;padding:20px;box-shadow:0 8px 30px rgba(127,119,221,.10);background:#fff}.dd-instruction{font-size:18px;font-weight:800;line-height:2.15;text-align:center;color:var(--purple-dark);background:var(--purple-soft);border-radius:16px;padding:18px;margin-bottom:16px}.dd-slot{display:inline-flex;align-items:center;justify-content:center;min-width:96px;height:38px;padding:0 10px;margin:0 3px;border:2px dashed #d8d3f5;border-radius:10px;background:#fff;color:var(--muted);font-size:14px;font-weight:900;vertical-align:middle}.dd-slot.filled{border-style:solid;background:var(--purple-soft);color:var(--purple-dark);cursor:pointer}.dd-slot.over{border-color:var(--purple);background:#E7E4FB}.dd-bank{display:flex;flex-wrap:wrap;justify-content:center;gap:14px;min-height:58px;margin:10px 0 6px}.dd-chip{display:inline-flex;align-items:center;justify-content:center;padding:12px 22px;border-radius:14px;background:var(--purple-soft);border:2px solid #AFA9EC;color:var(--purple-dark);font-size:17px;font-weight:900;cursor:grab;user-select:none;box-shadow:0 4px 14px rgba(127,119,221,.22)}.dd-chip.selected{background:var(--purple);border-color:var(--purple);color:#fff}.dd-chip.used{display:none}.dd-hint{text-align:center;color:var(--muted);font-size:12px;font-weight:800;margin:4px 0 0}.dd-hidden{display:none}.result{font-size:58px;font-weight:900;color:var(--orange);text-align:center}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#F9F8FF;border:1px solid var(--line);border-radius:14px;padding:13px;text-align:center}.metric b{display:block;font-size:25px;color:var(--purple)}.review,.study{border:1px solid var(--line);border-radius:14px;padding:13px;margin:10px 0}.study h3{margin:0 0 8px;color:var(--purple)}.study-row{display:flex;justify-content:space-between;gap:10px;align-items:center;border-top:1px solid var(--line);padding:9px 0}.study-row:first-of-type{border-top:0}.study-row a{color:var(--purple);font-weight:900}.good{color:#15803D}.bad{color:#B91C1C}@media(max-width:650px){.metric-grid{grid-template-columns:1fr}.match-row{grid-template-columns:1fr}.actions{flex-direction:column}.actions>*{width:100%}.dd-shell{padding:14px}.dd-instruction{font-size:16px}.study-row{align-items:flex-start;flex-direction:column}}
</style></head><body><div class="page"><div class="top"><div class="brand">ONES · Teacher Quiz</div><a class="back" href="<?=tq_h($returnTo!==''?$returnTo:'/lessons/lessons/academic/teacher_course.php')?>">← Back</a></div>
<?php if($mode==='intro'):?><section class="card"><span class="kicker">UNIT QUIZ · ATTEMPT <?=$attempt?></span><h1 class="title">Final unit quiz</h1><p class="lead">Your platform grade combines your work in the unit with this Quiz. You may receive a second opportunity when the first Quiz attempt is below 65%.</p><div class="chips"><span class="chip"><?=$totalQuestions?> questions</span><span class="chip">Maximum 2 attempts</span><span class="chip">Retry below 65%</span></div><a class="btn orange w100" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'quiz','q'=>0]))?>">Start quiz</a></section>
<?php elseif($mode==='quiz'&&$currentQuestion):?><section class="card"><span class="kicker">QUESTION <?=$questionIndex+1?> OF <?=$totalQuestions?></span><div class="progress"><div style="width:<?=(int)round((($questionIndex+1)/max(1,$totalQuestions))*100)?>%"></div></div><div class="question"><?=tq_h((string)($currentQuestion['question']??'Answer the question.'))?></div><?php if(!empty($currentQuestion['image'])):?><div class="question-media"><?=tq_media($currentQuestion['image'],'Question image')?></div><?php endif;?><form method="post">
<?php if(($currentQuestion['type']??'')==='multiple_choice'):?><?php $imageOptions=((string)($currentQuestion['option_type']??''))==='image';foreach(($currentQuestion['options']??[])as$index=>$option):$isImg=$imageOptions||tq_is_image($option);?><label class="option<?=$isImg?' image-option':''?>"><input type="radio" name="answer" value="<?=(int)$index?>" required><span class="option-content"><?=$isImg?tq_media($option,'Option '.chr(65+$index),'option-image'):tq_h((string)$option)?></span></label><?php endforeach;?>
<?php elseif(($currentQuestion['type']??'')==='match'):?><?php $rights=array_column($currentQuestion['pairs']??[],'right');foreach(($currentQuestion['pairs']??[])as$index=>$pair):?><div class="match-row"><strong class="match-left"><?=tq_is_image($pair['left']??'')?tq_media($pair['left'],'Match item','option-image'):tq_h((string)($pair['left']??''))?></strong><select class="select" name="answer[<?=(int)$index?>]" required><option value="">Choose</option><?php foreach($rights as$right):?><option value="<?=tq_h((string)$right)?>"><?=tq_h((string)$right)?></option><?php endforeach;?></select></div><?php endforeach;?>
<?php elseif(($currentQuestion['type']??'')==='drag_drop'):?><?php $ddWords=array_values((array)($currentQuestion['correct_words']??[]));$ddInstruction=tq_drag_instruction($currentQuestion);$parts=preg_split('/(___+)/',$ddInstruction,-1,PREG_SPLIT_DELIM_CAPTURE);?><div class="dd-shell" data-dd><div class="dd-instruction"><?php $slotIndex=0;foreach($parts as$part):if(preg_match('/^___+$/',$part)):?><span class="dd-slot" data-slot="<?=$slotIndex?>">___</span><?php $slotIndex++;else:?><?=tq_h($part)?><?php endif;endforeach;?></div><div class="dd-bank"><?php $shuffled=$ddWords;shuffle($shuffled);foreach($shuffled as$wordIndex=>$word):?><button type="button" class="dd-chip" draggable="true" data-word="<?=tq_h((string)$word)?>" data-chip="<?=$wordIndex?>"><?=tq_h((string)$word)?></button><?php endforeach;?></div><div class="dd-hint">Drag a word into a blank, or tap a word and then tap a blank.</div><?php foreach($ddWords as$index=>$word):?><input class="dd-hidden" type="text" name="answer[<?=(int)$index?>]" data-answer="<?=(int)$index?>" required><?php endforeach;?></div>
<?php elseif(($currentQuestion['type']??'')==='dictation'):?><div class="listen-box"><button class="listen-btn" type="button" data-audio="<?=tq_h((string)($currentQuestion['audio']??''))?>" data-text="<?=tq_h((string)($currentQuestion['correct']??''))?>">🔊 Listen</button><span class="listen-status">Listen, then type exactly what you hear.</span></div><input class="input" name="answer" autocomplete="off" required placeholder="Type what you hear">
<?php elseif(($currentQuestion['type']??'')==='fill'):?><input class="input" name="answer" required placeholder="Type the missing word or phrase">
<?php else:?><textarea class="input" name="answer" rows="3" required placeholder="Type your answer"></textarea><?php endif;?><div class="actions"><button class="btn orange" type="submit"><?=$questionIndex>=$totalQuestions-1?'See result →':'Next →'?></button><button class="btn light" type="submit" name="skip" value="1" formnovalidate>Skip</button></div></form></section>
<?php elseif($mode==='result'&&$isComplete):?><section class="card"><span class="kicker">ATTEMPT <?=$attempt?> RESULT</span><div class="result"><?=(int)$summary['final_percent']?>%</div><div class="metric-grid"><div class="metric"><b><?=(int)$summary['unit_percent']?>%</b>Unit activities</div><div class="metric"><b><?=(int)$summary['quiz_percent']?>%</b>Quiz</div><div class="metric"><b><?=(int)$summary['final_percent']?>%</b>Final grade</div></div><p class="lead" style="margin-top:18px">Final grade = 50% unit activities + 50% Quiz. The external Admin exam remains a separate 100% exam.</p><?php if(!empty($quizTypeFeedback)):?><div class="study"><h3>Debes estudiar más</h3><p class="lead" style="color:#534AB7;font-weight:900"><?=tq_h($quizStudyLabels)?></p><?php foreach($quizTypeFeedback as$item):?><div class="study-row"><span><strong><?=tq_h((string)$item['label'])?></strong> — <?=(int)$item['errors']?> de <?=(int)$item['questions']?> preguntas para repasar</span><a href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'review']))?>">Review errors</a></div><?php endforeach;?></div><?php else:?><div class="study"><h3>Excellent result</h3><p class="lead">No quiz activity types need additional review.</p></div><?php endif;?><div class="actions"><a class="btn light" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'review']))?>">Review answers</a><?php if($canRetry):?><a class="btn orange" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'restart'=>1]))?>">Second attempt</a><?php elseif($attempt===1):?><span class="btn light" style="cursor:default">Second attempt locked at 65%+</span><?php endif;?><a class="btn" href="<?=tq_h($courseReturn)?>">Save and return</a></div></section>
<?php elseif($mode==='review'&&$isComplete):?><section class="card"><span class="kicker">ANSWER REVIEW</span><h1 class="title"><?=(int)$result['percent']?>% Quiz</h1><?php foreach($quiz as$index=>$question):$answer=$answers[$index]??[];?><div class="review"><strong>Q<?=(int)$index+1?>. <?=tq_h((string)($question['question']??''))?></strong><div class="<?=!empty($answer['correct'])?'good':'bad'?>" style="margin-top:7px;font-weight:800"><?=!empty($answer['correct'])?'✓ Correct':'✗ Incorrect or partially correct'?> · <?=rtrim(rtrim(number_format((float)($answer['earned']??0),2),'0'),'.')?>/<?=(int)($answer['possible']??1)?> points</div><div style="margin-top:5px">Your answer: <?=tq_h(qz_review_answer_text($question,$answer['answer']??null))?></div><div>Correct answer: <?=tq_h(qz_review_correct_text($question))?></div><?php if(empty($answer['correct'])):?><div class="bad" style="margin-top:7px;font-weight:800">Study this concept again before retrying.</div><?php endif;?></div><?php endforeach;?><div class="actions"><a class="btn" href="?<?=tq_h(http_build_query(['assignment'=>$assignmentId,'unit'=>$unitId,'return_to'=>$returnTo,'mode'=>'result']))?>">Back to result</a><a class="btn light" href="<?=tq_h($courseReturn)?>">Return to course</a></div></section>
