(function(){var activeAudio=null;document.querySelectorAll('.listen-btn').forEach(function(button){button.addEventListener('click',function(){var audioUrl=(button.dataset.audio||'').trim();var text=(button.dataset.text||'').trim();if(activeAudio){activeAudio.pause();activeAudio.currentTime=0;activeAudio=null;}if('speechSynthesis'in window)window.speechSynthesis.cancel();button.classList.add('playing');button.textContent='🔊 Playing...';function reset(){button.classList.remove('playing');button.textContent='🔊 Listen';}if(audioUrl){activeAudio=new Audio(audioUrl);activeAudio.onended=reset;activeAudio.onerror=function(){activeAudio=null;if(text&&'speechSynthesis'in window){var u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;u.onend=reset;u.onerror=reset;window.speechSynthesis.speak(u);}else reset();};activeAudio.play().catch(function(){activeAudio.onerror();});}else if(text&&'speechSynthesis'in window){var utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.85;utterance.onend=reset;utterance.onerror=reset;window.speechSynthesis.speak(utterance);}else reset();});});document.querySelectorAll('[data-dd]').forEach(function(root){var selected=null;var chips=[].slice.call(root.querySelectorAll('.dd-chip'));var slots=[].slice.call(root.querySelectorAll('.dd-slot'));function sync(){slots.forEach(function(slot,i){var input=root.querySelector('[data-answer="'+i+'"]');if(input)input.value=slot.dataset.value||'';});}function clearSlot(slot){var chipId=slot.dataset.chip;if(chipId!==''){var chip=root.querySelector('[data-chip="'+chipId+'"]');if(chip)chip.classList.remove('used');}slot.dataset.value='';slot.dataset.chip='';slot.textContent='___';slot.classList.remove('filled');sync();}function place(chip,slot){if(slot.dataset.value)clearSlot(slot);slot.dataset.value=chip.dataset.word;slot.dataset.chip=chip.dataset.chip;slot.textContent=chip.dataset.word;slot.classList.add('filled');chip.classList.add('used');chips.forEach(function(c){c.classList.remove('selected');});selected=null;sync();}chips.forEach(function(chip){chip.addEventListener('dragstart',function(e){e.dataTransfer.setData('text/plain',chip.dataset.chip);});chip.addEventListener('click',function(){chips.forEach(function(c){c.classList.remove('selected');});selected=chip;chip.classList.add('selected');});});slots.forEach(function(slot){slot.dataset.value='';slot.dataset.chip='';slot.addEventListener('dragover',function(e){e.preventDefault();slot.classList.add('over');});slot.addEventListener('dragleave',function(){slot.classList.remove('over');});slot.addEventListener('drop',function(e){e.preventDefault();slot.classList.remove('over');var chip=root.querySelector('[data-chip="'+e.dataTransfer.getData('text/plain')+'"]');if(chip)place(chip,slot);});slot.addEventListener('click',function(){if(selected){place(selected,slot);}else if(slot.dataset.value){clearSlot(slot);}});});sync();});})();
</script></body></html>
